import { clamp01 } from '../core/contracts.js';
export function personalRelevance(item={},context=null){if(!context)return{available:false,score:null,reason:'NO_USER_CONTEXT'};let score=0,reasons=[];if((context.savedPlaceIds||[]).includes(item.placeId)){score+=.45;reasons.push('SAVED_PLACE');}if((context.watchSubjectIds||[]).includes(item.subjectId||item.eventId)){score+=.4;reasons.push('WATCH_MATCH');}if((context.tripPlaceIds||[]).includes(item.placeId)){score+=.35;reasons.push('TRIP_MATCH');}const interests=new Set(context.interests||[]);if((item.topics||[]).some(x=>interests.has(x))){score+=.2;reasons.push('INTEREST_MATCH');}return{available:true,score:clamp01(score),reasons,derivedOnlyFromExplicitContext:true};}
export function rankForMe(items=[],context=null){if(!context)return[];return items.map(item=>({item,relevance:personalRelevance(item,context)})).filter(x=>x.relevance.score>0).sort((a,b)=>b.relevance.score-a.relevance.score);}
